<?php
function feedback_progress_html($f){
 $labels=FeedbackService::progressLabels();$html='<section class="feedback-review-note"><h2>处理进度（不影响审核或奖励）</h2><p>'.e($labels[$f['progress_status']]??'尚未登记处理进度').'</p><ol class="feedback-progress-timeline">';
 foreach($f['progress_events'] as $event)$html.='<li><strong>'.e($labels[$event['to_status']]??$event['to_status']).'</strong> · '.e($event['created_at']).'<p>'.nl2br(e($event['public_note'])).'</p></li>';
 return $html.'</ol></section>';
}
function account_feedback_page($pdo,$uid){
    $labels=array('pending'=>'待审核','rewarded'=>'已奖励','rejected'=>'已驳回');$types=array('suggestion'=>'功能建议','bug'=>'问题反馈');
    $status=$_GET['status']??'';$page=$_GET['page']??'1';
    if(!is_string($status)||($status!==''&&!isset($labels[$status]))||!is_string($page)||preg_match('/^[1-9][0-9]{0,8}$/D',$page)!==1){http_response_code(400);return '<section class="mf-empty"><h1>反馈筛选参数无效</h1><p>请选择有效状态和页码。</p><a href="/feedback">返回反馈建议</a></section>';}
    $q=$pdo->prepare('SELECT status,COUNT(*) total FROM feedback_submissions WHERE user_id=? GROUP BY status');$q->execute(array($uid));$counts=array('all'=>0,'pending'=>0,'rewarded'=>0,'rejected'=>0);foreach($q->fetchAll() as $r){$counts['all']+=(int)$r['total'];if(isset($counts[$r['status']]))$counts[$r['status']]=(int)$r['total'];}
    $total=$counts[$status?:'all'];$pages=max(1,(int)ceil($total/20));$current=min((int)$page,$pages);$where='f.user_id=?';$args=array($uid);if($status!==''){$where.=' AND f.status=?';$args[]=$status;}
    $q=$pdo->prepare('SELECT f.id,f.feedback_no,f.type,f.subject,f.body,f.status,f.reward_cents,f.admin_note,f.created_at,f.progress_status,w.id reward_id FROM feedback_submissions f LEFT JOIN wallet_transactions w ON w.id=f.reward_transaction_id AND w.user_id=f.user_id AND w.type="feedback_reward" AND w.amount_cents=f.reward_cents WHERE '.$where.' ORDER BY f.id DESC LIMIT 20 OFFSET '.(($current-1)*20));$q->execute($args);$items=$q->fetchAll();
    $url=function($s,$p=1){return '/feedback?'.http_build_query(array('status'=>$s,'page'=>$p),'','&',PHP_QUERY_RFC3986);};$tabs='';$options='<option value="">状态：全部</option>';
    foreach(array(''=>'全部')+$labels as $key=>$label){$tabs.='<a href="'.e($url($key)).'"'.($status===$key?' aria-current="page"':'').'>'.$label.' ('.$counts[$key?:'all'].')</a>';if($key!=='')$options.='<option value="'.$key.'"'.($status===$key?' selected':'').'>'.$label.'</option>';}
    $old=$_SESSION['_feedback_old']??array();unset($_SESSION['_feedback_old']);$selected=isset($types[$old['type']??''])?$old['type']:'suggestion';$key=bin2hex(random_bytes(24));$_SESSION['_feedback_submission_keys'][$key]=1;while(count($_SESSION['_feedback_submission_keys'])>40)array_shift($_SESSION['_feedback_submission_keys']);
    $radios='';foreach($types as $value=>$label)$radios.='<label><input type="radio" name="type" value="'.$value.'"'.($selected===$value?' checked':'').'><span>'.$label.'</span></label>';
    $form='<section class="mf-submit" id="feedback-form" aria-labelledby="feedback-form-title"><h2 id="feedback-form-title">提交新反馈</h2><form method="post" action="/feedback" data-submit-lock>'.csrf_field().'<input type="hidden" name="submission_key" value="'.e($key).'"><fieldset class="mf-types"><legend>反馈类型</legend><div>'.$radios.'</div></fieldset><div class="mf-field"><label for="feedback-subject">反馈标题</label><input id="feedback-subject" name="subject" maxlength="200" placeholder="用一句话概括你的建议。" value="'.e($old['subject']??'').'" required></div><div class="mf-field"><label for="feedback-body">详细描述</label><div class="mf-description"><textarea id="feedback-body" name="body" maxlength="5000" placeholder="请描述遇到的问题、使用场景或改进建议…" aria-describedby="feedback-safety feedback-counter" required>'.e($old['body']??'').'</textarea><span id="feedback-counter" class="mf-counter">最多 5000 字</span></div></div><div class="mf-submit-actions"><button class="ao-button ao-primary" type="submit" data-idle-label="提交反馈">提交反馈</button><p id="feedback-safety">请勿填写密码、密钥或完整订阅链接。</p></div><p class="mf-submit-hint" hidden>正在提交，请勿重复点击。</p></form></section>';
    $info='<aside class="mf-guide"><h2>你的建议，值得被认真对待。</h2><ol><li><span>01</span>提交反馈</li><li><span>02</span>管理员审核与说明</li><li><span>03</span>审核通过后按规则发放奖励</li></ol><div><p>是否奖励及金额由管理员审核决定，提交不代表一定获奖；实际奖励入账后可在余额中查询。</p><a class="ao-button" href="/wallet">查看我的余额 ↗</a></div><div><p>订单交付或售后问题，请提交关联订单工单。</p><a class="ao-button" href="/tickets#new-ticket">前往我的工单 ↗</a></div></aside>';
    $icon='<svg aria-hidden="true" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 24 4 30l8-4c17 4 23-17 9-21C6 0-4 15 6 24Z"/><circle cx="10" cy="15" r=".8"/><circle cx="16" cy="15" r=".8"/><circle cx="22" cy="15" r=".8"/></svg>';
    $rows='';foreach($items as $f){$rewarded=$f['status']==='rewarded';$credited=$rewarded&&(int)$f['reward_cents']>0&&!empty($f['reward_id']);$review=!empty($f['admin_note'])?'管理员说明：'.mb_substr($f['admin_note'],0,180,'UTF-8'):mb_substr($f['body'],0,100,'UTF-8');$progress=FeedbackService::progressLabels()[$f['progress_status']]??'尚未登记';
        $rows.='<article class="mf-feedback"><span class="mf-icon">'.$icon.'</span><div class="mf-copy"><div class="mf-title"><h3><a href="/feedback/'.(int)$f['id'].'">'.e($f['subject']).'</a></h3><span class="mf-badge'.($rewarded?' is-rewarded':'').'">'.e($labels[$f['status']]??'状态待确认').'</span><span class="mf-badge">'.e($types[$f['type']]??'反馈').'</span></div><p class="mf-meta">反馈编号 '.e($f['feedback_no']).' · 提交于 <time datetime="'.e(str_replace(' ','T',$f['created_at'])).'">'.e(substr($f['created_at'],0,16)).'</time></p><p>'.e($review).'</p>'.($rewarded&&(int)$f['reward_cents']>0?'<p class="mf-reward">奖励 ¥'.WalletService::formatAmount((int)$f['reward_cents']).' <span>· '.($credited?'已入账户余额。':'请在详情中核对入账记录。').'</span></p>':'').'<p>处理进度：'.e($progress).'（独立于审核状态）</p></div><nav class="mf-actions" aria-label="反馈 '.(int)$f['id'].' 的操作"><a href="/feedback/'.(int)$f['id'].'">查看详情 ↗</a>'.($credited?'<a href="/wallet?type=feedback_reward&amp;range=all">查看奖励流水 ↗</a>':'').'</nav></article>';
    }
    $pager='<span>共 '.$total.' 条 · 第 '.$current.' / '.$pages.' 页</span>';foreach(array(-1=>'上一页',1=>'下一页') as $step=>$label){$enabled=$step<0?$current>1:$current<$pages;$pager.=$enabled?'<a rel="'.($step<0?'prev':'next').'" href="'.e($url($status,$current+$step)).'">'.$label.'</a>':'<span aria-disabled="true">'.$label.'</span>';if($step<0)$pager.='<b aria-current="page">'.$current.'</b>';}
    $empty='<div class="mf-empty"><h3>暂无匹配的反馈记录</h3><p>提交后可在这里查看审核、奖励及独立处理进度。</p><a href="/feedback">查看全部反馈</a></div>';
    return '<div class="mf-page"><header class="ao-welcome mf-welcome"><div><p class="ao-kicker">FEEDBACK &amp; SUGGESTIONS</p><h1>反馈建议</h1><p>说说你的想法，让产品变得更好。</p></div></header><div class="mf-top-grid">'.$form.$info.'</div><section class="mf-mine" aria-label="我的反馈"><header class="mf-list-head"><h2>我的反馈</h2><form method="get" action="/feedback"><label class="mf-sr-only" for="feedback-status">反馈审核状态</label><select id="feedback-status" name="status">'.$options.'</select><button type="submit">筛选</button></form></header><nav class="mf-tabs" aria-label="反馈状态筛选">'.$tabs.'</nav><div class="mf-list">'.($rows?:$empty).'</div><nav class="mf-pagination" aria-label="反馈记录分页">'.$pager.'</nav></section><p class="mf-note">反馈建议用于产品改进；需处理具体订单问题，请前往<a href="/tickets">我的工单</a>。</p></div><script>(function(){var form=document.querySelector(".mf-submit form"),body=form.querySelector("textarea"),counter=document.getElementById("feedback-counter"),button=form.querySelector("button[type=submit]"),hint=form.querySelector(".mf-submit-hint"),busy=false;function count(){counter.textContent="当前 "+Array.from(body.value).length+" / 5000 字"}body.addEventListener("input",count);count();form.addEventListener("submit",function(event){if(busy){event.preventDefault();return}busy=true;button.disabled=true;button.textContent="正在提交…";hint.hidden=false});window.addEventListener("pageshow",function(){busy=false;button.disabled=false;button.textContent="提交反馈";hint.hidden=true;count()})})();</script>';
}
function register_feedback_routes($router,$pdo,$config){
 $router->get('/feedback',function()use($config,$pdo){$uid=Security::requireUser();page('反馈建议',account_feedback_page($pdo,$uid),$config);});
 $router->post('/feedback',function()use($config,$pdo){$uid=Security::requireUser();post_csrf();try{$key=isset($_POST['submission_key'])?$_POST['submission_key']:'';if(!is_string($key)||!preg_match('/^[A-Za-z0-9_-]{16,80}$/D',$key)||!isset($_SESSION['_feedback_submission_keys'][$key]))throw new InvalidArgumentException('提交令牌已过期，请刷新页面。');$id=(new FeedbackService($pdo))->create($uid,isset($_POST['type'])?$_POST['type']:'',isset($_POST['subject'])?$_POST['subject']:'',isset($_POST['body'])?$_POST['body']:'',$key);unset($_SESSION['_feedback_submission_keys'][$key]);flash('success','反馈已提交，感谢你的建议。');}catch(Exception $e){$_SESSION['_feedback_old']=array();foreach(array('type','subject','body') as $field)if(isset($_POST[$field])&&is_string($_POST[$field]))$_SESSION['_feedback_old'][$field]=$_POST[$field];flash('error',$e->getMessage());}redirect('/feedback');});
 $router->get('/feedback/{id}',function($id)use($config,$pdo){$uid=Security::requireUser();try{$f=(new FeedbackService($pdo))->findMine($uid,(int)$id);}catch(Exception $e){http_response_code(404);return page('反馈不存在','<div class="empty service-ui-empty"><h1>反馈不存在或无权查看</h1><p>请返回反馈列表查看你提交的记录。</p><a class="secondary-button" href="/feedback">返回反馈列表</a></div>',$config);}$labels=array('pending'=>'待审核','rewarded'=>'已通过并奖励','rejected'=>'已驳回');$body='<div class="feedback-detail-page pc-feedback-detail"><a class="secondary-button" href="/feedback">← 返回反馈列表</a><section class="feedback-detail-card"><span class="eyebrow">FEEDBACK / '.e($f['feedback_no']).'</span><header class="ux-page-head"><div><h1>'.e($f['subject']).'</h1><p>反馈详情与处理记录</p></div></header><h2>审核与奖励</h2><p><span class="feedback-status feedback-status-'.e($f['status']).'">'.e($labels[$f['status']]??$f['status']).'</span>　'.e($f['created_at']).'</p><h2>反馈内容</h2><div class="feedback-body">'.nl2br(e($f['body'])).'</div>'.(!empty($f['admin_note'])?'<div class="feedback-review-note"><b>审核说明</b><p>'.nl2br(e($f['admin_note'])).'</p></div>':'').((int)$f['reward_cents']>0?'<div class="feedback-reward-note">奖励已入消费余额：<strong>'.e(money($f['reward_cents'])).'</strong></div>':'').feedback_progress_html($f).'</section></div>';page('反馈详情',$body,$config);});
}
